 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            y0 = min(y for y, _ in cells)
            y1 = max(y for y, _ in cells)
            x0 = min(x for _, x in cells)
            x1 = max(x for _, x in cells)
            objects.append({
                'color': color, 'cells': cells, 'y0': y0, 'y1': y1,
                'x0': x0, 'x1': x1, 'height': y1 - y0 + 1,
            })
    return objects


def _has_enclosed_zero(obj):
    y0, y1, x0, x1 = obj['y0'], obj['y1'], obj['x0'], obj['x1']
    occupied = {(y - y0, x - x0) for y, x in obj['cells']}
    hh, ww = y1 - y0 + 1, x1 - x0 + 1
    outside = set()
    q = deque()
    for y in range(hh):
        for x in range(ww):
            if y in (0, hh - 1) or x in (0, ww - 1):
                if (y, x) not in occupied and (y, x) not in outside:
                    outside.add((y, x))
                    q.append((y, x))
    while q:
        y, x = q.popleft()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if (0 <= ny < hh and 0 <= nx < ww and
                    (ny, nx) not in occupied and (ny, nx) not in outside):
                outside.add((ny, nx))
                q.append((ny, nx))
    return any((y, x) not in occupied and (y, x) not in outside
               for y in range(hh) for x in range(ww))


def _overlap_groups(objects):
    remaining = set(range(len(objects)))
    groups = []
    while remaining:
        seed = remaining.pop()
        group = {seed}
        changed = True
        while changed:
            changed = False
            lo = min(objects[i]['x0'] for i in group)
            hi = max(objects[i]['x1'] for i in group)
            for i in list(remaining):
                if objects[i]['x0'] <= hi and objects[i]['x1'] >= lo:
                    remaining.remove(i)
                    group.add(i)
                    changed = True
        groups.append(sorted(group, key=lambda i: (objects[i]['y0'], objects[i]['x0'])))
    return groups


def transform(grid):
    h, w = len(grid), len(grid[0])
    objects = _components(grid)
    closed = [i for i, obj in enumerate(objects) if _has_enclosed_zero(obj)]
    open_ = [i for i, obj in enumerate(objects) if i not in closed]
    out = [[0] * w for _ in range(h)]

    # Closed shapes are packed against the top; open shapes against the bottom.
    for indices, from_top in ((closed, True), (open_, False)):
        subset = [objects[i] for i in indices]
        for local_group in _overlap_groups(subset):
            group = [subset[j] for j in local_group]
            total_height = sum(obj['height'] for obj in group)
            y = 0 if from_top else h - total_height
            for obj in group:
                dy = y - obj['y0']
                for old_y, x in obj['cells']:
                    ny = old_y + dy
                    if 0 <= ny < h:
                        out[ny][x] = obj['color']
                y += obj['height']
    return out


